            { id: 'u6-196', type: 'grammar', topic: 'past simple regular', q: '"like" → past simple = ___.', options: ['like', 'liked', 'liking', 'likeed'], correct: 1, explanation: 'like → liked (verb ends in -e, just add -d).' },
            { id: 'u6-197', type: 'grammar', topic: 'past simple regular', q: '"finish" → past simple = ___.', options: ['finish', 'finishs', 'finished', 'finishen'], correct: 2, explanation: 'finish → finished. Regular past simple with -ed.' },
            { id: 'u6-198', type: 'grammar', topic: 'past simple irregular', q: 'know → ___ (past simple)', options: ['knowed', 'knew', 'known', 'knowing'], correct: 1, explanation: 'know → knew. An irregular past form.' },
            { id: 'u6-199', type: 'grammar', topic: 'past simple irregular', q: 'speak → ___ (past simple)', options: ['speaked', 'spoke', 'spoken', 'speaking'], correct: 1, explanation: 'speak → spoke. An irregular past form.' },
            { id: 'u6-200', type: 'grammar', topic: 'past simple irregular', q: 'eat → ___ (past simple)', options: ['eated', 'ated', 'ate', 'eaten'], correct: 2, explanation: 'eat → ate. An irregular past form.' },
            { id: 'u6-201', type: 'grammar', topic: 'past simple irregular', q: 'sleep → ___ (past simple)', options: ['sleeped', 'slept', 'slep', 'sleeping'], correct: 1, explanation: 'sleep → slept. An irregular past form.' },
            { id: 'u6-202', type: 'grammar', topic: 'past simple irregular', q: 'drink → ___ (past simple)', options: ['drinked', 'drank', 'drunk', 'drinking'], correct: 1, explanation: 'drink → drank. An irregular past form.' },
            { id: 'u6-203', type: 'grammar', topic: 'past simple irregular', q: 'buy → ___ (past simple)', options: ['buyed', 'bought', 'buyt', 'buying'], correct: 1, explanation: 'buy → bought. An irregular past form.' },
            { id: 'u6-204', type: 'grammar', topic: 'past simple questions', q: '"Where ___ Marco Polo born?"', options: ['was', 'did', 'is', 'do'], correct: 0, explanation: 'For "be" use was/were directly in past questions.' },
            { id: 'u6-205', type: 'grammar', topic: 'past simple questions', q: '"___ Polo travel with?" (with whom)', options: ['Who did', 'Who was', 'Who do', 'Who were'], correct: 0, explanation: 'Past question with main verb (travel) → Who did + subject + base verb.' },
            { id: 'u6-206', type: 'grammar', topic: 'past simple regular', q: 'For verbs ending in "consonant + y" (e.g., study), past simple is ___.', options: ['add -ed', 'change y to i and add -ed', 'double the consonant', 'no change'], correct: 1, explanation: 'consonant + y → drop y, add -ied. study → studied, try → tried, marry → married.' },
            { id: 'u6-207', type: 'vocabulary', topic: 'opinion adjectives', q: '"It was funny" describes something ___.', options: ['that makes you sad', 'that makes you laugh', 'expensive', 'old'], correct: 1, explanation: 'Funny = makes you laugh. Different from "fun" (enjoyable).' },
            { id: 'u6-208', type: 'vocabulary', topic: 'opinion adjectives', q: '"fun" and "funny" are ___.', options: ['the same', 'different', 'opposite', 'plural'], correct: 1, explanation: 'fun = enjoyable. funny = makes you laugh. They are different!' },
            { id: 'u6-209', type: 'vocabulary', topic: 'asking what people did', q: '"How was your weekend?" — a polite reply: ___.', options: ['Why do you ask?', 'It was great, thanks. And yours?', 'No idea.', 'Mind your business!'], correct: 1, explanation: 'A polite reply gives an opinion + thanks + asks back.' },
            { id: 'u6-210', type: 'vocabulary', topic: 'lifelogging', q: 'A lifelogging "fitness tracker" can record ___.', options: ['steps and exercise', 'colours', 'songs', 'recipes'], correct: 0, explanation: 'Fitness trackers record steps, exercise, heart rate.' },
            { id: 'u6-211', type: 'arrangement', topic: 'time expressions', parts: ['I', 'was', 'born', 'on the 1st of January', '.'], explanation: 'Subject + was born + on + date.' },
            { id: 'u6-212', type: 'arrangement', topic: 'word focus: write', parts: ['Please', 'write', 'down', 'your name', '.'], explanation: 'write down — phrasal verb meaning "note on paper".' },
            { id: 'u6-213', type: 'arrangement', topic: 'thank you messages', parts: ['I', 'look forward', 'to', 'hearing from you', '.'], explanation: 'Formal: I look forward to + -ing.' },
            { id: 'u6-214', type: 'arrangement', topic: 'thank you messages', parts: ['Thanks', 'for', 'coming', 'to my party', '.'], explanation: 'Informal: Thanks for + -ing + extra.' },
            { id: 'u6-215', type: 'vocabulary', topic: 'famous faces', q: 'Sally Ride was an astronaut who ___ in 1983.', options: ['travelled into space', 'painted', 'wrote books', 'studied art'], correct: 0, explanation: 'Sally Ride travelled into space in 1983 — first American woman in space.' },
            { id: 'u6-216', type: 'vocabulary', topic: 'famous faces', q: 'Arthur Honegger ___ in 1955.', options: ['painted', 'died', 'started a business', 'travelled'], correct: 1, explanation: 'Arthur Honegger (composer) died in 1955.' },
            { id: 'u6-217', type: 'grammar', topic: 'past simple irregular', q: 'fall → ___ (past simple)', options: ['falled', 'fell', 'fallen', 'falling'], correct: 1, explanation: 'fall → fell. An irregular past form.' },
            { id: 'u6-218', type: 'grammar', topic: 'past simple irregular', q: 'find → ___ (past simple)', options: ['finded', 'found', 'fund', 'finding'], correct: 1, explanation: 'find → found. An irregular past form.' },
            { id: 'u6-219', type: 'arrangement', topic: 'past simple', parts: ['Marco Polo', 'died', 'in 1324', '.'], explanation: 'Subject + verb-ed + in + year.' },
            { id: 'u6-220', type: 'arrangement', topic: 'past simple', parts: ['Many people', 'lived', 'in the caves', 'until the fifteenth century', '.'], explanation: 'Subject + verb-ed + place + until + time period.' }
